def fill_enclosed(grid, fill=4):
    """Every monochrome region not touching the border becomes fill."""
    from collections import deque
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and not seen[a][b] and grid[a][b]==grid[i][j]:
                seen[a][b]=True; q.append((a,b))
    return [[fill if not seen[i][j] else v for j,v in enumerate(row)] for i,row in enumerate(grid)]

