def fill_enclosed_rects(grid, fill=4):
    """Every rectangular monochrome region not touching the border becomes fill."""
    from collections import deque
    h,w=len(grid),len(grid[0])
    lab=[[-1]*w for _ in range(h)]; out=[row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if lab[i][j]<0:
                col=grid[i][j]; cells=[(i,j)]; lab[i][j]=1; st=[(i,j)]
                while st:
                    a,b=st.pop()
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and lab[x][y]<0 and grid[x][y]==col:
                            lab[x][y]=1; cells.append((x,y)); st.append((x,y))
                if not any(a in(0,h-1) or b in(0,w-1) for a,b in cells):
                    r0=min(a for a,_ in cells); r1=max(a for a,_ in cells)
                    c0=min(b for _,b in cells); c1=max(b for _,b in cells)
                    if len(cells)==(r1-r0+1)*(c1-c0+1):
                        for a,b in cells: out[a][b]=fill
    return out

